import sys, json

d = json.load(sys.stdin)
msgs = d.get("messages", [])
question = ""
for m in msgs:
    if m.get("origin") == "user":
        question = m.get("text", "")
        break

# Emittiere hop.rag_question (wird per set_context-Edge nach context.rag_question promoviert)
# + store-select tool_call als Body.
# WICHTIG: op_select erfordert explizites columns-Array (kein SELECT *).
out = {
    "header": {
        "rag_question": question
    },
    "messages": [{
        "origin": "assistant",
        "type": "tool_call",
        "id": "q-sel",
        "text": json.dumps({"operation": "select", "table": "corpus", "columns": ["doc_id", "text"]})
    }]
}
sys.stdout.write(json.dumps(out))
